def _build_component_06():
    def rounded(num, den, mode):
        if mode == "half_up":
            return (num + den // 2) // den
        return num // den

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for pos, event in enumerate(data["events"]):
            seq = event.get("sequence", 0)
            if seq > cutoff:
                continue
            identity = event.get("id", "anonymous:" + str(pos))
            key = (seq, event.get("revision", 0), pos)
            if identity not in winners or key > winners[identity][0]:
                winners[identity] = (key, event)
        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            quantity = event.get("quantity", 1)
            raw = event["price"] * quantity
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, data["rounding"])
            tax = rounded(raw * event.get("tax_bp", 0), 10000, data["rounding"])
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            account = event.get("account", "default")
            currency = event.get("currency", "USD")
            key = account + "|" + currency
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        best_vector = None
        best_selection = None

        def search(selection, constraints):
            nonlocal best_vector, best_selection
            # Validate all currently selected versions against every accumulated bound.
            for name, version in selection.items():
                if any(not (lo <= version <= hi) for lo, hi in constraints.get(name, [])):
                    return
            unresolved = next((n for n in names if n in constraints and n not in selection), None)
            if unresolved is None:
                # The constraints represent exactly the dependency closure.
                if best_vector is None:
                    vector = tuple(selection.get(n, -1) for n in names)
                    best_vector, best_selection = vector, dict(selection)
                else:
                    vector = tuple(selection.get(n, -1) for n in names)
                    if vector > best_vector:
                        best_vector, best_selection = vector, dict(selection)
                return
            ranges = constraints[unresolved]
            rows = []
            for row in packages[unresolved]:
                version = row["version"]
                if version in blocked.get(unresolved, []):
                    continue
                if unresolved in pins and pins[unresolved] != version:
                    continue
                if all(lo <= version <= hi for lo, hi in ranges):
                    rows.append(row)
            # Descending is useful but exhaustive search preserves global objective.
            for row in sorted(rows, key=lambda r: r["version"], reverse=True):
                version = row["version"]
                new_sel = dict(selection)
                new_sel[unresolved] = version
                new_constraints = {n: list(v) for n, v in constraints.items()}
                valid = True
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    new_constraints.setdefault(target, []).append((dep["min"], dep["max"]))
                    if target in new_sel and not all(lo <= new_sel[target] <= hi
                                                      for lo, hi in new_constraints[target]):
                        valid = False
                        break
                if not valid:
                    continue
                # Any cycle in the currently selected active edges invalidates this branch.
                edges = {}
                for source, source_version in new_sel.items():
                    source_row = next(r for r in packages[source] if r["version"] == source_version)
                    edges[source] = []
                    for dep in source_row.get("deps", []):
                        f = dep.get("feature", "")
                        if (not f or f in features) and dep["name"] in new_sel:
                            edges[source].append(dep["name"])
                state, done = set(), set()
                def visit(node):
                    if node in state:
                        return False
                    if node in done:
                        return True
                    state.add(node)
                    if any(not visit(child) for child in edges.get(node, [])):
                        return False
                    state.remove(node)
                    done.add(node)
                    return True
                if not all(visit(node) for node in edges):
                    continue
                search(new_sel, new_constraints)

        initial = {name: [(bounds[0], bounds[1])] for name, bounds in roots.items()}
        if not initial:
            return {"versions": {}}
        search({}, initial)
        if best_selection is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_selection}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bits = {node: 0 for node in range(data["n"])}
        for i, node in enumerate(required):
            bits[node] |= 1 << i
        full = (1 << len(required)) - 1
        start_state = (data["source"], bits[data["source"]], data["coupons"])
        start_time = data["start"]
        dist = {start_state: start_time}
        queue = [(start_time, *start_state)]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if dist.get(state) != time:
                continue
            if node == data["target"] and mask == full and remaining == 0:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    options.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
                for duration, left in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = edge["v"]
                    new_state = (nxt, mask | bits[nxt], left)
                    if arrival < dist.get(new_state, float("inf")):
                        dist[new_state] = arrival
                        heapq.heappush(queue, (arrival, *new_state))
        return {"arrival": None}
    return solve


